#!/usr/bin/env python3
"""Ross's transcript transcriber.

Scans every friend/* branch in full history, finds commits marked
'Friend-Message: 1', compares their full SHAs against every episode file on
main, and appends any missing utterance to the episode it declares.
Existing entries are never rewritten.
"""
import os
import re
import subprocess
import sys

REPO = sys.argv[1] if len(sys.argv) > 1 else "/home/runner/work/wt-main"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
HEADER_RE = re.compile(r"^(Friend-Message|Speaker|Episode|Reply-To|Correction-Request):", re.M)


def git(*args):
    return subprocess.run(["git", "-C", REPO] + list(args), check=True,
                          capture_output=True, text=True).stdout


def message_of(sha):
    return git("show", sha, "-s", "--format=%B")


def body_of(text):
    """Return the utterance text: everything after the header block."""
    lines = text.split("\n")
    i = 0
    for idx, line in enumerate(lines):
        if line.startswith("Reply-To:") or line.startswith("Correction-Request:"):
            i = idx + 1
    # skip the blank line(s) after the headers
    while i < len(lines) and lines[i].strip() == "":
        i += 1
    body = "\n".join(lines[i:]).strip("\n")
    return body


def field(text, name):
    m = re.search(r"^%s:\s*(.*)$" % name, text, re.M)
    return m.group(1).strip() if m else ""


def main():
    git("fetch", "origin", "--prune")
    known = set()
    for root, _dirs, files in os.walk(REPO):
        if "/.git" in root:
            continue
        for f in files:
            if re.fullmatch(r"E\d+\.md", f):
                with open(os.path.join(root, f), encoding="utf-8") as fh:
                    known.update(re.findall(r"@ ([0-9a-f]{40})", fh.read()))

    pending = []
    for b in BRANCHES:
        raw = git("log", "--format=%H%x1f%cI%x1f%s", "origin/friend/" + b)
        for line in raw.strip().split("\n"):
            if not line.strip():
                continue
            sha, cdate, subject = line.split("\x1f")
            if not subject.startswith("friend:"):
                continue
            text = message_of(sha)
            if "Friend-Message: 1" not in text:
                continue
            if sha in known:
                continue
            pending.append((cdate, sha, b, text))

    # order by commit time, then full sha; reply-to respected where both available
    def key(item):
        cdate, sha, b, text = item
        reply = field(text, "Reply-To")
        return (cdate, sha)

    pending.sort(key=key)

    by_ep = {}
    for cdate, sha, b, text in pending:
        ep = field(text, "Episode") or "S04/E06"
        by_ep.setdefault(ep, []).append((cdate, sha, b, text))

    for ep, items in sorted(by_ep.items()):
        path = os.path.join(REPO, ep + ".md")
        if not os.path.exists(path):
            print("MISSING FILE for", ep)
            continue
        with open(path, encoding="utf-8") as fh:
            content = fh.read()
        chunks = []
        for cdate, sha, b, text in items:
            speaker = field(text, "Speaker")
            body = body_of(text)
            chunks.append(
                "**%s** (%s)\n\nSource: friend/%s @ %s\n\n%s: %s\n\n"
                % (speaker, cdate.replace("+00:00", "Z"), b, sha, speaker, body)
            )
        if not content.endswith("\n"):
            content += "\n"
        content += "\n" + "\n".join(chunks).rstrip("\n") + "\n"
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(content)
        print("appended %d utterances to %s" % (len(items), path))


if __name__ == "__main__":
    main()

